function toRegimeCode(regime) {
  const norm2 = String(regime || "").toUpperCase().replace(/_/g, "-");
  if (norm2.includes("RISK-ON")) return "RISK-ON";
  if (norm2.includes("RISK-OFF")) return "RISK-OFF";
  if (norm2.includes("TIGHTENING")) return "CENTRAL-BANK-TIGHTENING";
  if (norm2.includes("EASING")) return "CENTRAL-BANK-EASING";
  if (norm2.includes("STAGFLATION")) return "STAGFLATION";
  if (norm2.includes("GOLDILOCKS")) return "GOLDILOCKS";
  if (norm2.includes("DISINFLATION")) return "DISINFLATIONARY";
  if (norm2.includes("INFLATION")) return "INFLATIONARY";
  if (norm2.includes("EXPANSION")) return "GROWTH-EXPANSION";
  if (norm2.includes("SLOWDOWN")) return "GROWTH-SLOWDOWN";
  if (norm2.includes("RECESSION")) return "RECESSIONARY";
  return "MIXED-UNCLEAR";
}
