var RolloutManager = class {
  constructor() {
    this.currentTrustLevel = 2;
    // Default to Level 2: UI/WORKFLOW
    this.highRiskCategories = [
      "BROKER_EXECUTION",
      "ORDER_CANCELLATION",
      "ACCOUNT_PERMISSIONS",
      "FINANCIAL_CALCULATION",
      "RISK_LIMITS",
      "AUTHENTICATION",
      "PAYMENTS",
      "PRIVACY_SECURITY"
    ];
  }
  setTrustLevel(level) {
    this.currentTrustLevel = level;
  }
  getTrustLevel() {
    return this.currentTrustLevel;
  }
  checkEligibility(proposal) {
    const isHighRisk = this.highRiskCategories.some(
      (cat) => proposal.category.toUpperCase().includes(cat) || proposal.title.toUpperCase().includes(cat) || proposal.summary.toUpperCase().includes(cat)
    );
    let requiredTrustLevel = 2;
    if (proposal.category.includes("EDUCATIONAL") || proposal.category.includes("CONTENT")) {
      requiredTrustLevel = 1;
    } else if (proposal.complexity === "HIGH" || isHighRisk) {
      requiredTrustLevel = 3;
    } else {
      requiredTrustLevel = 2;
    }
    if (isHighRisk) {
      return {
        allowed: false,
        trustLevel: this.currentTrustLevel,
        requiredTrustLevel: 3,
        isHighRisk: true,
        reason: "BLOCKED: High-risk financial execution, risk limit, or auth modification requires explicit human administrator verification."
      };
    }
    const allowed = this.currentTrustLevel >= requiredTrustLevel;
    return {
      allowed,
      trustLevel: this.currentTrustLevel,
      requiredTrustLevel,
      isHighRisk: false,
      reason: allowed ? `Permitted under Trust Level ${this.currentTrustLevel}` : `Requires Trust Level ${requiredTrustLevel} (Current: ${this.currentTrustLevel})`
    };
  }
};

